// Generate two random quaternions (w,x,y,z) as doubles from fuzzer
const double (*a_arr)[4] = FUZZ_PARAM(double[4]);
const double (*b_arr)[4] = FUZZ_PARAM(double[4]);

// Extract components
double aw = a_arr[0][0];
double ax = a_arr[0][1];
double ay = a_arr[0][2];
double az = a_arr[0][3];
double bw = b_arr[0][0];
double bx = b_arr[0][1];
double by = b_arr[0][2];
double bz = b_arr[0][3];

// Enforce finite values to avoid NaNs/Infs during normalization
if (!(std::isfinite(aw) && std::isfinite(ax) && std::isfinite(ay) && std::isfinite(az) &&
      std::isfinite(bw) && std::isfinite(bx) && std::isfinite(by) && std::isfinite(bz))) {
    FUZZ_BAIL();
}

// Construct Eigen quaternions (w, x, y, z)
Eigen::Quaterniond qa(aw, ax, ay, az);
Eigen::Quaterniond qb(bw, bx, by, bz);

// Require non-zero finite norms, then normalize to get unit quaternions as inputs
double na = qa.norm();
double nb = qb.norm();
if (!(std::isfinite(na) && na > 0.0 && std::isfinite(nb) && nb > 0.0)) { FUZZ_BAIL(); }
qa.normalize();
qb.normalize();

// Target call: addQ applies hemisphere correction and returns the elementwise sum (not normalized)
Eigen::Quaterniond qres = addQ(qa, qb);

// Persist the result; caller may normalize if a unit quaternion is needed
Eigen::Quaterniond *q_sum = new Eigen::Quaterniond(qres);
// Mark that this quaternion is not guaranteed to be normalized
FUZZ_SET_ATTR_INT(q_sum, "normalized", 0);

// Validation: Inputs are normalized unit quaternions and finite; output is stored for reuse.
